CLASS zcl_todo_list DEFINITION PUBLIC.

  PUBLIC SECTION.
    INTERFACES z2ui5_if_app.

    TYPES:
      BEGIN OF ty_todo,
        done TYPE abap_bool,
        text TYPE string,
      END OF ty_todo.

    DATA todos    TYPE STANDARD TABLE OF ty_todo WITH EMPTY KEY.
    DATA new_text TYPE string.

  PROTECTED SECTION.
    DATA client TYPE REF TO z2ui5_if_client.

    METHODS view_display.

  PRIVATE SECTION.
ENDCLASS.


CLASS zcl_todo_list IMPLEMENTATION.

  METHOD z2ui5_if_app~main.

    me->client = client.
    IF client->check_on_init( ).
      todos = VALUE #( ( text = `Open the playground` done = abap_true )
                       ( text = `Describe an app` )
                       ( text = `Download it for abapGit` ) ).
      view_display( ).
    ELSEIF client->check_on_navigated( ).
      view_display( ).
    ELSEIF client->check_on_event( `ADD` ).
      IF new_text IS INITIAL.
        client->message_toast_display( `Type what there is to do first` ).
        RETURN.
      ENDIF.
      INSERT VALUE #( text = new_text ) INTO TABLE todos.
      CLEAR new_text.
      client->view_model_update( ).
    ELSEIF client->check_on_event( `CLEAR_DONE` ).
      DELETE todos WHERE done = abap_true.
      client->view_model_update( ).
    ENDIF.

  ENDMETHOD.


  METHOD view_display.

    DATA(view) = z2ui5_cl_ui5_view_builder=>factory(
        )->ele( n = `View` ns = `mvc`
            )->a( n = `displayBlock` v = `true`
            )->a( n = `height`       v = `100%`
            )->a( n = `xmlns`        v = `sap.m`
            )->a( n = `xmlns:mvc`    v = `sap.ui.core.mvc` ).

    DATA(page) = view->ele( `Shell`
        )->ele( `Page`
            )->a( n = `title` v = `My to-do list` ).

    page->ele( `HBox`
        )->a( n = `class` v = `sapUiSmallMargin`
        )->tag( `Input`
            )->a( n = `value`       v = client->_bind( new_text )
            )->a( n = `placeholder` v = `What is there to do?`
            )->a( n = `submit`      v = client->_event( `ADD` )
            )->a( n = `width`       v = `20rem`
        )->tag( `Button`
            )->a( n = `text`  v = `Add`
            )->a( n = `type`  v = `Emphasized`
            )->a( n = `press` v = client->_event( `ADD` )
            )->a( n = `class` v = `sapUiTinyMarginBegin`
        )->tag( `Button`
            )->a( n = `text`  v = `Delete the done ones`
            )->a( n = `press` v = client->_event( `CLEAR_DONE` )
            )->a( n = `class` v = `sapUiTinyMarginBegin` ).

    page->ele( `List`
        )->a( n = `items` v = client->_bind( todos )
        )->a( n = `class` v = `sapUiSmallMargin`
        )->ele( `CustomListItem`
            )->ele( `HBox`
                )->a( n = `alignItems` v = `Center`
                )->tag( `CheckBox`
                    )->a( n = `selected` v = `{DONE}`
                )->tag( `Text`
                    )->a( n = `text` v = `{TEXT}` ).

    client->view_display( view->stringify( ) ).

  ENDMETHOD.

ENDCLASS.
